'use strict';
const $=id=>document.getElementById(id),KEY='TCGshop-POS-ledger-v1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const yuan=n=>'¥'+(n/100).toFixed(2),uid=()=>crypto.randomUUID(),clone=o=>JSON.parse(JSON.stringify(o));
const DEFAULT_CATEGORIES=[],DEFAULT_COST_RATES=[],UNSELECTED='未选择';
const rateLabel=rate=>(rate/100).toFixed(2).replace(/\.?0+$/,'')+'%';
function newSku(products,start){if(!products){products=state.products;start=state.nextSku||1;}const max=products.reduce((n,p)=>/^\d+$/.test(p.sku)?Math.max(n,Number(p.sku)):n,0),next=Math.max(start||1,max+1);if(!integer(next,1))fail('SKU 数字序号已达上限');return String(next).padStart(6,'0');}
function legacySku(id){let h=14695981039346656037n;for(const c of id){h^=BigInt(c.codePointAt(0));h=BigInt.asUintN(64,h*1099511628211n)}return 'TCG-'+h.toString(16).padStart(16,'0').slice(-12).toUpperCase();}
const dayFormatter=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'});
const timeFormatter=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});
const day=(d=new Date())=>dayFormatter.format(d),time=t=>timeFormatter.format(new Date(t));
const seed=[['宝可梦 · 朱紫补充包','卡包',1500,900,36,'SV-001','◆','#e8eee4','#6f9c66'],['游戏王 · 基础补充包','卡包',2000,1200,24,'YG-001','✦','#ece6f0','#8875a0'],['宝可梦 · 训练家礼盒','礼盒',19800,13500,6,'SV-BOX','◇','#eee9df','#ad8853'],['闪卡 · 收藏单卡','单卡',6800,4200,8,'CARD-001','✧','#e0eaf1','#5b8da8'],['透明保护卡套 · 100枚','配件',1800,950,48,'ACC-001','▱','#e6eeeb','#6d9b8b'],['九宫格收藏册','配件',5800,3200,3,'ACC-002','▦','#eee6e3','#b58275'],['航海王 · 补充包','卡包',2500,1600,18,'OP-001','☀','#f1ecdc','#b69b54'],['卡牌收纳盒','配件',3500,1800,0,'ACC-003','▣','#e6e9ef','#7185a1']];
function initial(){const now=new Date().toISOString();const products=seed.map((s,i)=>({id:'sample-'+i,name:s[0],category:s[1],price:s[2],cost:s[3],stock:s[4],sku:s[5],symbol:s[6],tint:s[7],art:s[8],min:5}));return {version:1,demo:true,store:'我的卡牌小店',products,orders:[],expenses:[],movements:products.filter(p=>p.stock).map(p=>({id:uid(),productId:p.id,name:p.name,sku:p.sku,code:p.code,delta:p.stock,after:p.stock,type:'示例期初',note:'示例库存，可在设置中清空',time:now})),stocktakes:[],cart:[],discount:0,payment:'微信'};}
let ledgerRaw=null;
let state,readOnly=false,mobileCartOpen=false,navigationOpen=false;
try{const raw=localStorage.getItem(KEY);ledgerRaw=raw;state=raw?validate(JSON.parse(raw)):validate(initial());}catch(e){state={version:1,demo:false,store:'我的卡牌小店',products:[],orders:[],expenses:[],movements:[],stocktakes:[],cart:[],discount:0,payment:'微信'};readOnly=true;}
let page='pos',category='全部',query='',receiptQuery='',movementType='全部',reportFrom=day(),reportTo=day(),toastTimer;
if(readOnly){state.categories=[...DEFAULT_CATEGORIES];state.costRates=[...DEFAULT_COST_RATES];}
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
function fail(s){throw Error(s)}
function integer(n,min=0){return Number.isSafeInteger(n)&&n>=min&&n<=1000000000;}
function validate(s){
 if(!s||s.version!==1||typeof s.demo!=='boolean'||typeof s.store!=='string'||!s.store.trim()||s.store.length>60)fail('账本格式不正确');
 if(s.stocktakes===undefined)s.stocktakes=[];
 for(const k of ['products','orders','expenses','movements','stocktakes','cart'])if(!Array.isArray(s[k])||s[k].length>100000)fail('账本缺少 '+k);
 const ids=new Set();for(const p of s.products){if(typeof p.id!=='string'||!/^[-a-zA-Z0-9]+$/.test(p.id)||ids.has(p.id)||typeof p.name!=='string'||!p.name.trim()||typeof p.category!=='string'||typeof p.sku!=='string'||!p.sku.trim()||!integer(p.price)||!integer(p.cost)||!integer(p.stock,-1000000000)||!integer(p.min))fail('商品数据不正确');ids.add(p.id);}
 if(new Set(s.products.map(p=>p.sku)).size!==s.products.length)fail('SKU 重复');
 const orderIds=new Set();for(const o of s.orders){if(!o||typeof o.id!=='string'||!/^[-a-zA-Z0-9]+$/.test(o.id)||orderIds.has(o.id)||!validDate(o.time)||!['已收款','微信','支付宝','现金'].includes(o.payment)||typeof o.refunded!=='boolean'||!Array.isArray(o.lines)||!o.lines.length||!integer(o.discount)||!integer(o.total)||!integer(o.cost)||!integer(o.cashReceived)||!integer(o.change)||o.cashReceived-o.total!==o.change)fail('小票数据不正确');orderIds.add(o.id);for(const l of o.lines)if(!ids.has(l.productId)||typeof l.name!=='string'||!integer(l.qty,1)||!integer(l.price,1)||!integer(l.cost))fail('小票商品不正确');const subtotal=o.lines.reduce((a,l)=>a+l.qty*l.price,0);if(o.discount>subtotal||o.total!==subtotal-o.discount||o.cost!==o.lines.reduce((a,l)=>a+l.qty*l.cost,0)||!integer(subtotal))fail('小票金额不一致');if(o.refunded&&!validDate(o.refundTime))fail('退货日期不正确');}
 for(const e of s.expenses)if(!e||typeof e.id!=='string'||!integer(e.amount,1)||typeof e.note!=='string'||!validDate(e.time))fail('支出数据不正确');
 for(const m of s.movements)if(!m||typeof m.id!=='string'||!ids.has(m.productId)||typeof m.name!=='string'||typeof m.type!=='string'||typeof m.note!=='string'||!Number.isSafeInteger(m.delta)||Math.abs(m.delta)>1000000000||!integer(m.after,-1000000000)||!validDate(m.time)||(m.device!==undefined&&!validDevice(m.device)))fail('库存流水不正确');
 const stocktakeIds=new Set();for(const t of s.stocktakes){if(!t||typeof t.id!=='string'||!/^[-a-zA-Z0-9]+$/.test(t.id)||stocktakeIds.has(t.id)||!validDate(t.time)||typeof t.note!=='string'||!t.note.trim()||t.note.length>200||!Array.isArray(t.lines)||!t.lines.length||t.lines.length>100000||!Number.isSafeInteger(t.qtyDiff)||!Number.isSafeInteger(t.amountDiff))fail('盘库单不正确');stocktakeIds.add(t.id);const lineIds=new Set();let qtyDiff=0,amountDiff=0;for(const l of t.lines){if(!l||!ids.has(l.productId)||lineIds.has(l.productId)||typeof l.name!=='string'||!l.name.trim()||typeof l.sku!=='string'||!l.sku.trim()||!integer(l.before,-1000000000)||!integer(l.after,-1000000000)||!Number.isSafeInteger(l.delta)||l.delta!==l.after-l.before||!integer(l.unitCost)||!Number.isSafeInteger(l.amountDiff)||l.amountDiff!==l.delta*l.unitCost)fail('盘库明细不正确');lineIds.add(l.productId);qtyDiff+=l.delta;amountDiff+=l.amountDiff;if(!Number.isSafeInteger(qtyDiff)||!Number.isSafeInteger(amountDiff))fail('盘库差异超出范围');}if(qtyDiff!==t.qtyDiff||amountDiff!==t.amountDiff)fail('盘库汇总不一致');}
 const cartIds=new Set();for(const l of s.cart){if(!ids.has(l.productId)||s.products.find(p=>p.id===l.productId).deleted||cartIds.has(l.productId)||!integer(l.qty,1)||(l.unitPrice!==undefined&&!integer(l.unitPrice,1)))fail('购物车不正确');cartIds.add(l.productId);}
 if(!integer(s.discount)||!['微信','支付宝','现金'].includes(s.payment))fail('收银设置不正确');
 if(s.categories===undefined)s.categories=[];
 if(s.costRates===undefined)s.costRates=[...DEFAULT_COST_RATES];
 if(!Array.isArray(s.categories)||s.categories.length>200||s.categories.some(c=>typeof c!=='string'||!c.trim()||c.length>40||c==='全部'||c===UNSELECTED)||new Set(s.categories).size!==s.categories.length)fail('分类选项不正确');
 if(!Array.isArray(s.costRates)||s.costRates.length>200||s.costRates.some(r=>!integer(r)||r>10000)||new Set(s.costRates).size!==s.costRates.length)fail('成本比例选项不正确');
 if(s.optionSchema!==2){s.categories=s.categories.filter(c=>!['卡包','单卡','礼盒','配件'].includes(c));s.costRates=s.costRates.filter(r=>![7500,7000,8000,8500,9000].includes(r));s.optionSchema=2;}
 if(s.productSchema!==2){const used=new Set();for(const p of s.products){p.code=p.sku;let sku=legacySku(p.id);while(used.has(sku))sku=newSku(s.products);p.sku=sku;used.add(sku)}s.productSchema=2;}
 for(const p of s.products){if(p.deleted!==undefined&&typeof p.deleted!=='boolean')fail('商品删除状态不正确');if(p.cover!==undefined&&p.cover!==''&&(typeof p.cover!=='string'||p.cover.length>600000||!/^data:image\/jpeg;base64,[A-Za-z0-9+/]+={0,2}$/.test(p.cover)&&!/^asset:[a-f0-9]{64}$/.test(p.cover)))fail('商品封面格式不正确');if(typeof p.code!=='string'||!p.code.trim()||p.code.length>80||/[\u0000-\u001f\u007f]/.test(p.code))fail('商品编码不正确');if(!s.categories.includes(p.category))p.category=UNSELECTED;if(p.costRate!==undefined&&(!integer(p.costRate)||p.costRate>10000))fail('商品成本比例不正确');if(p.costRate!==undefined&&!s.costRates.includes(p.costRate))delete p.costRate;}
 if(new Set(s.products.filter(p=>!p.deleted).map(p=>p.code)).size!==s.products.filter(p=>!p.deleted).length)fail('商品编码重复');
 for(const o of s.orders){o.actor=validateActor(o.actor);validateRefunds(o);}
 for(const m of s.movements)m.actor=validateActor(m.actor);
 for(const t of s.stocktakes)t.actor=validateActor(t.actor);
 for(const e of s.expenses)e.actor=validateActor(e.actor);
 const maxSku=s.products.reduce((n,p)=>/^\d+$/.test(p.sku)?Math.max(n,Number(p.sku)):n,0);
 if(s.nextSku===undefined)s.nextSku=Math.max(1,maxSku+1);if(!integer(s.nextSku,1))fail('SKU 序号不正确');s.nextSku=Math.max(s.nextSku,maxSku+1);
 POSSyncCore.upgrade(s);POSSyncCore.validateShops(s);return s;
}
function validateActor(a){if(a===undefined)return {id:'legacy',username:'历史记录',name:'历史记录（未记录账号）'};if(!a||typeof a.id!=='string'||!/^[-a-zA-Z0-9]+$/.test(a.id)||a.id.length>100||typeof a.username!=='string'||!a.username.trim()||a.username.length>32||typeof a.name!=='string'||!a.name.trim()||a.name.length>60)fail('操作账号资料不正确');return a;}
function actorLabel(a){return a?.name&&a.name!=='历史记录（未记录账号）'?a.name:'历史记录';}
function validDevice(d){return !!d&&typeof d.id==='string'&&/^[-a-zA-Z0-9]+$/.test(d.id)&&d.id.length<=100&&typeof d.name==='string'&&!!d.name.trim()&&d.name.length<=60;}
function validDate(s){return typeof s==='string'&&Number.isFinite(Date.parse(s));}
function transact(fn,rerender=true){if(rerender==='cart')return transactCart(fn);if(!POSAuth.user()){toast('请先登录账号');return false;}if(readOnly){toast('本地账本读取异常，请先导出原始备份，再恢复有效备份');return false;}try{if(POSAuth.user().role==='staff'&&state.activeShopId!==POSAuth.user().shopId)fail('店员只能操作归属店铺');if(localStorage.getItem(KEY)!==ledgerRaw)fail('账本已由其他窗口更新，请刷新后操作');const next=clone(state);fn(next);POSSyncCore.capture(next);validate(next);const saved=POSAssets.serialize(next);localStorage.setItem(KEY,saved);ledgerRaw=saved;state=next;window.POSSync?.changed();if(rerender==='cart'&&page==='pos')refreshCart();else if(rerender)render();return true;}catch(e){toast('未保存：'+e.message);return false;}}
function moneyInput(id,allowZero=false){const raw=$(id).value.trim();if(!/^\d+(\.\d{1,2})?$/.test(raw))fail('金额最多保留两位小数');const n=Math.round(Number(raw)*100);if(!integer(n,allowZero?0:1))fail('请输入有效金额');return n;}
// Cart edits keep the immutable business snapshot and avoid recapturing every inventory.
function transactCart(fn){
 try{
  const user=POSAuth.requireUser();if(readOnly)fail('本地账本读取异常，请先恢复有效备份');
  if(user.role==='staff'&&state.activeShopId!==user.shopId)fail('店员只能操作归属店铺');
  if(localStorage.getItem(KEY)!==ledgerRaw)fail('账本已由其他窗口更新，请刷新后操作');
  const next={...state,cart:state.cart.map(line=>({...line}))};fn(next);
  const products=new Map(next.products.map(p=>[p.id,p])),seen=new Set();let subtotal=0;
  if(next.cart.length>100000)fail('订单商品过多');
  for(const line of next.cart){const p=products.get(line.productId);if(!p||p.deleted||seen.has(line.productId)||!integer(line.qty,1)||(line.unitPrice!==undefined&&!integer(line.unitPrice,1)))fail('购物车不正确');seen.add(line.productId);subtotal+=cartUnitPrice(line,p)*line.qty;}
  if(!Number.isSafeInteger(subtotal)||!integer(next.discount)||next.discount>subtotal)fail('订单金额不正确');
  const saved=POSAssets.serialize(next);localStorage.setItem(KEY,saved);ledgerRaw=saved;state=next;
  if(page==='pos')refreshCart();else render();return true;
 }catch(e){toast('未保存：'+e.message);return false;}
}
function qtyInput(id,allowZero=false){const v=$(id).value;if(!/^\d+$/.test(v)||!integer(Number(v),allowZero?0:1))fail('数量必须为'+(allowZero?'非负':'正')+'整数');return Number(v);}
function guarded(fn){try{fn()}catch(e){toast(e.message)}}
function modal(title,html){$('dialogTitle').textContent=title;$('dialogBody').innerHTML=html;$('dialog').showModal();}
function field(label,id,value,type='text',extra=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function barcodeField(value){return `<div class="field"><label for="pCode">商品编码 / 条码</label><div class="barcode-field"><input id="pCode" type="text" value="${esc(value)}" required maxlength="80" placeholder="手动输入或扫码"><button type="button" id="scanSku" aria-label="扫描商品条码">▥ 扫描</button></div></div>`;}
function wireProductScanner(id){$('scanSku').onclick=()=>ProductCodeScanner.open($('pCode'),value=>{const exists=activeProducts().some(p=>p.id!==id&&p.code===value);toast(exists?'已填入条码，但已有商品使用此编码，请检查后再保存':'条码已填入，请确认商品信息后保存')});$('pCode').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('pPrice').focus()}});}
function selectField(label,id,options){return `<div class="field"><label for="${id}">${label}</label><select id="${id}">${options.map(v=>`<option>${esc(v)}</option>`).join('')}</select></div>`;}
function actions(label){return `<div class="form-actions"><button type="button" data-cancel>取消</button><button class="primary" type="submit">${label}</button></div>`;}
function wireForm(fn){$('dialogBody').querySelector('[data-cancel]')?.addEventListener('click',()=>$('dialog').close());$('dialogBody').querySelector('form')?.addEventListener('submit',e=>{e.preventDefault();guarded(fn)});}
// Wait for IME composition to finish before replacing the search input.
function wireSearch(id,save){
 const input=$(id);if(!input)return;let composing=false;
 function update(e){if(composing||e.isComposing||!input.isConnected)return;const start=input.selectionStart,end=input.selectionEnd;save(input.value);render();const next=$(id);next?.focus();next?.setSelectionRange(start,end);}
 input.addEventListener('compositionstart',()=>{composing=true;});
 input.addEventListener('compositionend',e=>{composing=false;update(e);});
 input.addEventListener('input',update);
}
function activeProducts(){return state.products.filter(p=>!p.deleted)}
function product(id){return state.products.find(p=>p.id===id)}
function totals(productsById=new Map(state.products.map(p=>[p.id,p]))){let subtotal=0,count=0;for(const l of state.cart){subtotal+=cartUnitPrice(l,productsById.get(l.productId))*l.qty;count+=l.qty;}return {subtotal,total:Math.max(0,subtotal-state.discount),count};}
function render(){
 document.querySelectorAll('#main .settings-fold').forEach(d=>{const title=d.querySelector('summary>span')?.textContent;if(title)settingsExpanded.set(title,d.open);});
 if(!POSAuth.user()){POSAuth.renderGate();return;}
 document.body.classList.remove('auth-locked');$('authScreen').hidden=true;try{POSShops.ensure();}catch(e){POSAuth.logout();toast(e.message);return;}$('accountQuick').textContent=state.store+(POSAuth.isAdmin()?' ▾':'');$('accountQuick').disabled=!POSAuth.isAdmin();$('accountQuick').title=POSAuth.isAdmin()?'选择店铺':'当前归属店铺';
 const names={pos:'收银台',products:'商品与库存',movements:'出入库记录',receipts:'销售小票',reports:'经营概览',settings:'数据与设置'};
 $('pageTitle').textContent=$('crumb').textContent=names[page];document.querySelector('.store b').textContent=state.store;
 document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');});
 document.body.classList.toggle('has-pos',page==='pos');document.body.classList.toggle('cart-open',page==='pos'&&mobileCartOpen);
 $('main').innerHTML=(readOnly?'<div class="notice">本地账本读取异常，已停止写入。请前往「数据与设置」导出原始数据后恢复备份。</div>':'')+({pos:renderPOS,products:renderProducts,movements:renderMovements,receipts:renderReceipts,reports:renderReports,settings:renderSettings}[page])();wirePage();syncCartAccessibility();
}
function renderPOS(){const products=activeProducts(),productsById=new Map(state.products.map(p=>[p.id,p])),t=totals(productsById),search=query.trim().toLowerCase();const list=products.filter(p=>(!search||(p.name+' '+p.code+' '+p.sku).toLowerCase().includes(search))).sort((a,b)=>Number(b.stock>0)-Number(a.stock>0));return `${state.demo?'<div class="banner"><div><strong>示例账本</strong> 正式使用前，请在设置中清空示例数据。</div><span class="badge">体验模式</span></div>':''}<div class="pos-layout"><section><div class="section-title"><div><h2>选择商品 <small> / ${products.length} 件商品</small></h2><p class="sub">点击商品加入订单，确认收款后扣减库存</p></div></div><div class="toolbar pos-controls"><div class="search-wrap"><span>⌕</span><input id="search" placeholder="搜索名称、编码或 SKU" aria-label="搜索商品" value="${esc(query)}"></div><button class="secondary" id="scanSearch">▥ 扫码</button></div>${renderFavorites()}<div class="product-grid">${list.map(p=>`<button class="product-card ${p.stock<=0?'out-of-stock':''}" data-add="${p.id}" aria-label="添加 ${esc(p.name)}"><div class="product-art" style="--tint:${safeColor(p.tint,'#e8eee4')};--art:${safeColor(p.art,'#6f9c66')}">${p.cover?`<img loading="lazy" decoding="async" class="product-cover" src="${esc(p.cover)}" alt="${esc(p.name)}封面">`:``}${p.stock<=0?`<span class="badge red">无库存</span>`:''}<div style="${p.cover?'display:none':''}" class="${p.category==='礼盒'?'art-box':p.category==='配件'?'art-sleeve':'art-card'}"><i>${esc(p.symbol||'◇')}</i>${p.category==='卡包'||p.category==='单卡'?'<small>TCGshop</small>':''}</div></div><span class="add-dot">＋</span><div class="product-info"><b>${esc(p.name)}</b><small>${esc(p.category)} · ${esc(p.code)}</small><div><strong>${p.price?yuan(p.price):'收款时定价'}</strong><span>库存 ${p.stock}</span></div></div></button>`).join('')||'<div class="empty">没有找到商品</div>'}</div></section>${renderCart(t,productsById)}</div>`;}
function renderCart(t,productsById){return `<button class="cart-shade" id="cartShade" aria-label="关闭当前订单"></button><aside id="currentCart" class="cart" aria-label="当前订单"><button class="cart-close" id="closeCart" aria-label="收起当前订单">×</button><div class="cart-head"><div><h3>当前订单 <span class="badge" id="cartCount">${t.count}</span></h3></div><button class="text-button" id="clearCart">清空</button></div><div class="cart-items">${state.cart.map(l=>{const p=productsById.get(l.productId);return `<div data-cart-item="${p.id}" class="cart-row ${cartUnitPrice(l,p)?'':'needs-price'}"><div class="cart-row-top"><span>${esc(p.name)}</span><strong>${cartUnitPrice(l,p)?yuan(cartUnitPrice(l,p)*l.qty):'待填写单价'}</strong></div><div class="cart-row-bottom"><button class="cart-price-button ${cartUnitPrice(l,p)?'':'price-required'}" data-cart-price="${p.id}">${cartUnitPrice(l,p)?yuan(cartUnitPrice(l,p))+' / 件 · 修改':'＋ 输入单价（必填）'}</button><div class="stepper"><button data-qty="${p.id}" data-delta="-1" aria-label="减少 ${esc(p.name)}">−</button><span>${l.qty}</span><button data-qty="${p.id}" data-delta="1" aria-label="增加 ${esc(p.name)}">＋</button></div></div></div>`}).join('')||'<div class="empty"><span class="empty-symbol">▤</span>暂无商品<br><small>选择商品或扫码加入订单</small></div>'}</div><div class="cart-bottom"><div class="sum-line"><span>商品小计</span><span id="subtotal">${yuan(t.subtotal)}</span></div><div class="sum-line"><label for="discount">整单优惠（元）</label><input class="discount-input" id="discount" type="number" min="0" step="0.01" value="${(state.discount/100).toFixed(2)}"></div><div class="total-line"><span>应收金额</span><strong id="due">${yuan(t.total)}</strong></div><button class="primary pay-button" id="checkout" ${state.cart.length?'':'disabled'}><span>确认收款</span><span>→</span></button><p class="cart-note">确认实际到账后记账 · 同时更新库存</p></div></aside><button class="mobile-cart-bar" id="mobileCart" aria-controls="currentCart" aria-expanded="${mobileCartOpen}"><span>当前订单 · ${t.count} 件</span><strong>${yuan(t.total)}</strong><span>查看 / 结账 ↑</span></button>`;}
function safeColor(c,fallback){return /^#[\da-f]{6}$/i.test(c)?c:fallback;}
function productNameCompare(a,b){const collator=productNameCompare.collator||(productNameCompare.collator=new Intl.Collator('zh-Hans',{numeric:true,sensitivity:'base'})),aa=a.name.trim(),bb=b.name.trim(),rank=s=>/^\d/.test(s)?0:/^[A-Za-z]/.test(s)?1:2;return rank(aa)-rank(bb)||collator.compare(aa,bb)||collator.compare(a.sku,b.sku);}
function renderProducts(){const products=activeProducts(),search=query.trim().toLowerCase(),list=products.filter(p=>(p.name+' '+p.code+' '+p.sku).toLowerCase().includes(search)).slice().sort(productNameCompare);return `<div class="section-title"><div><h2>商品与库存</h2><p class="sub">${products.length} 件商品 · ${products.filter(p=>p.stock<=0).length} 件售罄</p></div><div class="section-actions">${POSAuth.isAdmin()?'<button class="secondary" id="stocktake">盘库</button>':''}<button class="primary" id="newProduct">＋ 新建商品</button></div></div><div class="toolbar inventory-controls"><div class="search-wrap"><span>⌕</span><input id="search" value="${esc(query)}" placeholder="搜索名称、编码或 SKU" aria-label="搜索商品"></div><button class="secondary" id="scanInventory">▥ 扫一扫</button></div><div class="panel table-wrap inventory-table"><table><thead><tr><th>商品 / 编码</th><th>售价</th><th>本产品成本</th><th>现有库存</th><th>库存状态</th><th>操作</th></tr></thead><tbody>${list.map(p=>`<tr><td><div class="inventory-product"><span class="inventory-thumb">${p.cover?`<img src="${esc(p.cover)}" alt="${esc(p.name)}封面">`:'◇'}</span><span><b>${esc(p.name)}</b><small>编码 ${esc(p.code)}</small><small>SKU ${esc(p.sku)}</small></span></div></td><td>${p.price?yuan(p.price):'收款时定价'}</td><td>${yuan(p.cost)}</td><td class="${p.stock<0?'negative-stock':''}">${p.stock}</td><td><span class="badge ${p.stock<=0?'red':'good'}">${p.stock<0?'负库存':p.stock===0?'售罄':'有库存'}</span></td><td><button data-edit="${p.id}">编辑</button><button data-stock="${p.id}" class="secondary">出入库</button><button data-delete="${p.id}" class="danger">删除</button></td></tr>`).join('')||'<tr><td colspan="6">'+(query.trim()?'没有匹配的商品':'暂无商品，请新建商品')+'</td></tr>'}</tbody></table></div><p class="hint">入库按移动加权平均更新成本；收款和退货保留成交时的价格与成本。</p>`;}
const signedQty=n=>(n>0?'+':'')+n,signedYuan=n=>(n>0?'+':n<0?'−':'')+yuan(Math.abs(n));
function renderStocktakeRecords(){if(!POSAuth.isAdmin())return '';const rows=state.stocktakes.slice().reverse().map(t=>`<tr><td><b>${esc(t.id)}</b><small>${time(t.time)}</small></td><td>${esc(t.note)}</td><td>${t.lines.length}</td><td class="${t.qtyDiff<0?'negative-stock':''}">${signedQty(t.qtyDiff)}</td><td class="${t.amountDiff<0?'negative-stock':''}">${signedYuan(t.amountDiff)}</td><td>${esc(actorLabel(t.actor))}</td><td><button data-stocktake-record="${esc(t.id)}">查看盘库表</button></td></tr>`).join('')||'<tr><td colspan="7">暂无盘库记录</td></tr>';return `<div class="panel stocktake-records"><div class="section-title"><div><h3>盘库数据表</h3><p class="sub">数量差异和金额差异按盘库时的商品成本计算</p></div></div><div class="table-wrap"><table><thead><tr><th>盘库单 / 时间</th><th>说明</th><th>商品数</th><th>数量差异</th><th>金额差异</th><th>操作人</th><th>操作</th></tr></thead><tbody>${rows}</tbody></table></div></div>`;}
function showStocktake(id){POSAuth.requireAdmin();const t=state.stocktakes.find(t=>t.id===id),productsById=new Map(state.products.map(p=>[p.id,p]));if(!t)fail('未找到盘库单');modal('盘库数据表',`<div class="receipt-meta"><span>盘库单 ${esc(t.id)}</span><span>${time(t.time)}</span><span>操作人：${esc(actorLabel(t.actor))}</span></div><p class="hint">${esc(t.note)}</p><div class="table-wrap"><table><thead><tr><th>商品 / SKU</th><th>账面数量</th><th>实盘数量</th><th>数量差异</th><th>商品成本</th><th>金额差异</th></tr></thead><tbody>${t.lines.map(l=>{const cover=productsById.get(l.productId)?.cover||'';return `<tr><td><div class="inventory-product stocktake-product"><span class="inventory-thumb">${cover?`<img src="${esc(cover)}" alt="${esc(l.name)}封面">`:'◇'}</span><span><b>${esc(l.name)}</b><small>SKU ${esc(l.sku)}</small></span></div></td><td>${l.before}</td><td>${l.after}</td><td class="${l.delta<0?'negative-stock':''}">${signedQty(l.delta)}</td><td>${yuan(l.unitCost)}</td><td class="${l.amountDiff<0?'negative-stock':''}">${signedYuan(l.amountDiff)}</td></tr>`}).join('')}</tbody><tfoot><tr><th colspan="3">合计差异</th><th>${signedQty(t.qtyDiff)}</th><th></th><th>${signedYuan(t.amountDiff)}</th></tr></tfoot></table></div><div class="form-actions"><button class="primary" id="stocktakeDone">完成</button></div>`);$('stocktakeDone').onclick=()=>$('dialog').close();}
function renderRecordGroups(rows,head,renderRow,empty,label){
 if(!rows.length)return `<div class="panel empty">${empty}</div>`;
 const groups=new Map();
 for(const row of rows){const date=day(new Date(row.time));if(!groups.has(date))groups.set(date,[]);groups.get(date).push(row);}
 return [...groups].map(([date,items])=>{const [year,month,dateNumber]=date.split('-');return `<section class="record-day" data-record-date="${date}"><div class="record-day-heading"><h3><time datetime="${date}">${year}年${Number(month)}月${Number(dateNumber)}日</time></h3><span>${items.length} 条记录</span></div><div class="panel table-wrap records-table"><table aria-label="${date} ${label}"><thead><tr>${head.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${items.map(renderRow).join('')}</tbody></table></div></section>`;}).join('');
}
function recordTimeCompare(a,b){return Date.parse(b.time)-Date.parse(a.time)||a.id.localeCompare(b.id);}
function renderMovements(){
 const rows=state.movements.filter(m=>movementType==='全部'||m.type===movementType).slice().sort(recordTimeCompare);
 return `<div class="section-title"><div><h2>出入库记录</h2><p class="sub">销售出库、采购入库、盘库、同步调整与退货统一追踪</p></div><button class="primary" id="newMovement">＋ 记录出入库</button></div>${renderStocktakeRecords()}<div class="filter-row"><select id="movementType" aria-label="流水类型">${['全部','采购入库','手动出库','编辑入库','编辑出库','盘点调整','盘库调整','同步调整','销售出库','销售退货','期初库存','示例期初'].map(t=>`<option ${t===movementType?'selected':''}>${t}</option>`).join('')}</select></div>${renderRecordGroups(rows,['时间','商品','类型','变动数量','变动后库存','操作人','说明'],m=>`<tr><td data-label="时间">${time(m.time)}</td><td data-label="商品">${esc(m.name)}</td><td data-label="类型"><span class="badge">${esc(m.type)}</span></td><td data-label="变动数量" style="color:${m.delta>0?'var(--green)':'var(--red)'}">${signedQty(m.delta)}</td><td data-label="变动后库存">${m.after}</td><td data-label="操作人">${esc(actorLabel(m.actor))}</td><td data-label="说明">${esc(m.note)}${POSAuth.isAdmin()?`<button class="danger compact-action" data-delete-movement="${esc(m.id)}">删除</button>`:''}</td></tr>`,'暂无出入库记录','出入库记录')}`;
}
function renderReceipts(){
 const rows=state.orders.flatMap(o=>[{kind:'sale',order:o,time:o.time,id:o.id,actor:o.actor},...o.refunds.map(r=>({kind:'refund',order:o,refund:r,time:r.time,id:r.id,actor:r.actor}))]).filter(row=>(row.id+row.order.id+row.order.lines.map(l=>l.name).join('')+actorLabel(row.actor)+(row.refund?.note||'')).toLowerCase().includes(receiptQuery.toLowerCase())).sort(recordTimeCompare);
 return `<div class="section-title"><div><h2>销售与退款记录</h2><p class="sub">原订单金额保持不变，每次退款单独记录</p></div><span class="badge">${state.orders.length} 笔销售 · ${state.orders.reduce((n,o)=>n+o.refunds.length,0)} 笔退款</span></div><div class="toolbar"><div class="search-wrap"><span>⌕</span><input id="receiptSearch" placeholder="搜索小票 / 商品 / 操作人" value="${esc(receiptQuery)}" aria-label="搜索小票"></div></div>${renderRecordGroups(rows,['类型','商品','金额','单号 / 时间','操作人','状态','操作'],row=>{const o=row.order,r=row.refund;return `<tr data-record-type="${row.kind}"><td data-label="类型"><span class="badge ${r?'red':'good'}">${r?'退款':'销售'}</span></td><td data-label="商品">${r?esc(r.lines.map(l=>o.lines[l.lineIndex].name+' × '+l.qty).join('、')):esc(o.lines[0].name)+(o.lines.length>1?' 等 '+o.lines.length+' 项':'')}</td><td data-label="金额" class="${r?'refund-amount':''}">${r?'−'+yuan(r.amount):yuan(o.total)}</td><td data-label="单号 / 时间"><b>${esc(row.id)}</b><small>${time(row.time)}</small>${r?'<small>原订单 '+esc(o.id)+'</small>':''}</td><td data-label="操作人">${esc(actorLabel(row.actor))}</td><td data-label="状态">${r?'已退款':refundStatus(o)}</td><td data-label="操作">${r?'<button data-refund="'+esc(r.id)+'" data-order="'+esc(o.id)+'">查看退款</button>':'<button data-receipt="'+esc(o.id)+'">查看小票</button><button data-print-order="'+esc(o.id)+'">打印</button>'}${POSAuth.isAdmin()?'<button class="danger compact-action" data-delete-receipt="'+esc(o.id)+'">删除小票</button>':''}</td></tr>`},'暂无销售与退款记录','销售与退款记录')}`;
}
function inRange(t){const d=day(new Date(t));return d>=reportFrom&&d<=reportTo;}
function renderReports(){const t=reportTotals(),ds=[],daily=new Map();const itemRows=reportSaleItems(t.sales,state.products).map(i=>`<tr><td class="report-product-name">${i.cover?`<img class="report-product-thumb" src="${esc(i.cover)}" alt="">`:`<span class="report-product-thumb report-product-placeholder">◇</span>`}<span>${esc(i.name)}</span></td><td>${i.qty}</td><td>${yuan(i.total)}</td></tr>`).join('')||'<tr><td colspan="3">当前日期范围内没有未退商品</td></tr>';for(const o of state.orders){const date=day(new Date(o.time));daily.set(date,(daily.get(date)||0)+o.total);}for(let i=6;i>=0;i--){const d=new Date(reportTo+'T12:00:00+08:00');d.setUTCDate(d.getUTCDate()-i);const date=day(d);const n=daily.get(date)||0;ds.push({date,n});}const max=Math.max(1,...ds.map(d=>d.n));return `<section class="reports-page"><div class="section-title report-heading"><div><h2>经营概览</h2><p class="sub">销售、退货、成本和支出，按实际发生日期统计</p></div><button id="addExpense" class="secondary">＋ 记录支出</button></div><div class="filter-row report-filters"><div class="report-date-range"><input id="reportFrom" type="date" value="${reportFrom}" aria-label="开始日期"><span>至</span><input id="reportTo" type="date" value="${reportTo}" aria-label="结束日期"></div><div class="report-presets"><button id="prevDayReport">上一天</button><button id="todayReport">今天</button><button id="weekReport">近 7 天</button></div></div><div class="stats">${[['净销售额',t.net,t.sales.length+' 笔成交 · 退货 '+yuan(t.returned)],['销售成本',t.cost,'按成交时的商品成本'],['经营支出',t.spend,t.expenses.length+' 笔经营支出'],['估算利润',t.profit,'净销售 − 成本 − 经营支出']].map(([label,n,hint])=>`<div class="stat"><span>${label}</span><strong>${yuan(n)}</strong><small>${hint}</small></div>`).join('')}</div><div class="panel report-items-panel"><div class="section-title"><h3>销售项目明细</h3><small>按销售日期汇总，扣除已退商品与优惠</small></div><div class="table-wrap"><table><thead><tr><th>商品名称</th><th>数量</th><th>总价</th></tr></thead><tbody>${itemRows}</tbody></table></div></div><div class="report-grid"><div class="panel"><h3>最近 7 天销售额</h3><p class="sub">截至 ${reportTo} · 收款额，未扣退货</p><div class="bars">${ds.map(d=>`<div class="bar-col"><span>${yuan(d.n)}</span><div class="bar" style="height:${d.n/max*140}px;--bar-share:${d.n/max*100}%"></div><small>${d.date.slice(5)}</small></div>`).join('')}</div></div><div class="panel"><h3>收款汇总</h3><p class="sub">所选日期范围内</p><div class="setting-row"><span>成交收款</span><b>${yuan(t.gross)}</b></div><div class="setting-row"><span>已退款</span><b>${yuan(t.returned)}</b></div><div class="setting-row"><span>净收款</span><b>${yuan(t.net)}</b></div></div></div><p class="hint">采购入库增加库存资产，销售时结转成本；不要把同一笔采购款重复记录为经营支出。手动出库／盘点损失尚未自动计入利润。</p></section>`;}
function appVersionLabel(){let version='1.1.0';try{version=window.NativePOS?.appVersion?.()||version;}catch{}return 'v'+version+(version.includes('test')?' 测试版':' 正式版');}
function renderSettings(){return `<div class="settings-intro"><h3>数据与设置</h3><p class="sub">管理店铺、账号、同步、打印机和小票样式。</p></div>${window.POSPrinter?.panel()||'<div class="panel printer-panel"><h3>小票机连接</h3><p class="hint">打印机模块尚未加载，请刷新预览页面后重试。</p></div>'}${window.POSPrinter?.stylePanel()||''}${POSShops.panel()}${POSAuth.panel()}${window.POSSync?.panel()||''}${POSAuth.isAdmin()?'<div class="panel"><h3>店铺设置</h3>':'<div hidden><h3>店铺设置</h3>'}<div class="setting-row"><div><b>${esc(state.store)}</b><p>显示在工作空间和销售小票上</p></div><button id="renameStore">修改店名</button></div></div><div class="panel"><h3>相机设置</h3><div class="field"><label for="cameraPreference">扫码与商品拍照使用的相机</label><select id="cameraPreference"><option value="">自动（优先后置相机）</option></select></div><p class="hint" id="cameraSettingsStatus">相机选项仅在本机保存。</p><button id="refreshCameras" class="secondary">授权并刷新相机列表</button></div>${POSAuth.isAdmin()?'<div class="panel"><h3>数据管理</h3>':'<div hidden><h3>数据管理</h3>'}<div class="setting-row"><div><b>导出账本备份</b><p>包括全部店铺的商品、库存、销售、退款、盘库、出入库、支出及本机当前订单。不含登录账号与同步设置；账号请通过 NAS 同步。</p></div><button id="exportBackup" class="secondary">↓ 导出 JSON</button></div><div class="setting-row"><div><b>恢复备份</b><p>先预览文件内容，再确认替换本机账本；替换前请导出当前备份。</p></div><button id="importBackup">↑ 选择备份</button><input id="importFile" type="file" accept=".json,application/json" hidden></div><div class="setting-row"><div><b>导入 Loyverse 商品</b><p>仅导入商品列表 CSV，包括名称、SKU、条码、分类、售价、成本和库存；图片需重新添加。</p></div><button id="loyverseImport" class="secondary">↑ 选择商品 CSV</button><input id="loyverseImportFile" type="file" accept=".csv,text/csv" hidden></div>${state.demo&&state.shops.length===1?'<div class="setting-row"><div><b>开始正式使用</b><p>清空示例商品以及体验期间生成的订单、盘库单和流水，创建自己的商品。</p></div><button class="danger" id="resetDemo">清空示例账本</button></div>':''}</div><div class="panel"><h3>当前版本</h3><button id="checkAppUpdate" class="secondary">检查更新</button><p class="hint">后台检查新版本，发现更新时提醒；未联网时跳过检查。</p><p class="hint">TCGshop POS · ${esc(appVersionLabel())}。收款与退款需实际完成后在此确认记账。</p><p class="hint">${window.NativePOS?'卸载或清除应用数据会移除本机账本，请先完成 NAS 同步或导出备份。':'清理浏览器网站数据会移除本机账本，请先完成 NAS 同步或导出备份。'}</p></div>`;}
const settingsExpanded=new Map();
function organizeSettings(){
 const main=$('main'),printer=main.querySelector('.printer-panel'),style=main.querySelector('.receipt-style-panel');
 if(printer&&style){const group=document.createElement('section');group.className='panel receipt-settings';const title=document.createElement('h3');title.textContent='小票与打印';group.append(title);printer.before(group);group.append(printer,style);}
 for(const panel of [...main.children]){
  if(!panel.classList.contains('panel')||panel.hidden||!panel.querySelector('button,input,select'))continue;
  const heading=panel.querySelector('h3'),title=heading?.textContent||'设置',details=document.createElement('details'),summary=document.createElement('summary'),label=document.createElement('span'),toggle=document.createElement('span');
  details.className='settings-fold';details.open=settingsExpanded.get(title)??(title==='小票与打印');label.textContent=title;toggle.className='fold-toggle';toggle.textContent=details.open?'收起':'展开';summary.append(label,toggle);details.append(summary);panel.before(details);details.append(panel);heading?.remove();
  details.addEventListener('toggle',()=>{if(details.isConnected)settingsExpanded.set(title,details.open);toggle.textContent=details.open?'收起':'展开';});
 }
}
function toggleCart(open){mobileCartOpen=open;document.body.classList.toggle('cart-open',open);$('mobileCart')?.setAttribute('aria-expanded',String(open));syncCartAccessibility();$(open?'closeCart':'mobileCart')?.focus();}
const cartFlights=new Set();
function flyCartFeedback(start){
 if(matchMedia('(prefers-reduced-motion:reduce)').matches||!Element.prototype.animate)return;
 const target=matchMedia('(max-width:640px)').matches&&!mobileCartOpen?$('mobileCart'):$('cartCount');
 if(!target)return;const end=target.getBoundingClientRect();if(!end.width||!end.height)return;
 // Bound concurrent feedback; rapid additions still save each item immediately.
 if(cartFlights.size>=4){const oldest=cartFlights.values().next().value;oldest.animation.cancel();oldest.node.remove();cartFlights.delete(oldest);}
 const x=Math.min(innerWidth-30,Math.max(30,start.left+start.width*.6)),y=Math.min(innerHeight-30,Math.max(30,start.top+Math.min(start.height*.4,80)));
 const node=document.createElement('span');node.className='cart-flight';node.textContent='+1';node.setAttribute('aria-hidden','true');node.style.left=(x-24)+'px';node.style.top=(y-24)+'px';document.body.append(node);
 const dx=end.left+end.width/2-x,dy=end.top+end.height/2-y;
 const animation=node.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:'translate('+dx*.42+'px,'+(dy*.42-65)+'px) scale(1.15)',opacity:1,offset:.45},{transform:'translate('+dx+'px,'+dy+'px) scale(.35)',opacity:0}],{duration:440,easing:'cubic-bezier(.2,.65,.35,1)'});
 const flight={node,animation};cartFlights.add(flight);const clean=()=>{node.remove();cartFlights.delete(flight);};animation.onfinish=()=>{clean();if(target.isConnected)cartFeedback(target);};animation.oncancel=clean;
}
function wireCart(){
 const on=(id,fn,event='onclick')=>{if($(id))$(id)[event]=fn;};
 on('mobileCart',()=>toggleCart(true));on('closeCart',()=>toggleCart(false));on('cartShade',()=>toggleCart(false));
 document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>addToCart(b.dataset.qty,Number(b.dataset.delta)));
 document.querySelectorAll('[data-cart-price]').forEach(b=>b.onclick=()=>guarded(()=>editCartPrice(b.dataset.cartPrice)));
 on('clearCart',()=>transact(s=>{s.cart=[];s.discount=0},'cart'));
 on('discount',()=>guarded(()=>{const n=moneyInput('discount',true);if(n>totals().subtotal)fail('优惠不能超过商品小计');transact(s=>s.discount=n,'cart')}),'onchange');
 on('checkout',()=>guarded(checkout));
}
function patchCartRow(current,next){
 if(current.nodeType===Node.TEXT_NODE){if(current.nodeValue!==next.nodeValue)current.nodeValue=next.nodeValue;return;}
 if(current.nodeType!==Node.ELEMENT_NODE)return;
 for(const attr of [...current.attributes])if(!next.hasAttribute(attr.name))current.removeAttribute(attr.name);
 for(const attr of next.attributes)if(current.getAttribute(attr.name)!==attr.value)current.setAttribute(attr.name,attr.value);
 if(current.childNodes.length!==next.childNodes.length){current.replaceChildren(...next.childNodes);return;}
 [...current.childNodes].forEach((node,i)=>{const fresh=next.childNodes[i];if(node.nodeType===fresh.nodeType&&node.nodeName===fresh.nodeName)patchCartRow(node,fresh);else node.replaceWith(fresh.cloneNode(true));});
}
const cartFeedbackAnimations=new WeakMap();
function cartFeedback(node,enter=false){
 if(!node||!node.animate||matchMedia('(prefers-reduced-motion:reduce)').matches)return;
 const previous=cartFeedbackAnimations.get(node),current=previous?getComputedStyle(node):null;
 const from=previous?{opacity:Number(current.opacity),transform:current.transform}:{opacity:enter?0:.45,transform:enter?'translateX(24px)':'none'};
 previous?.cancel();
 const animation=node.animate([from,{opacity:1,transform:'translateX(0)'}],{duration:enter?300:260,easing:'cubic-bezier(.16,1,.3,1)'});
 cartFeedbackAnimations.set(node,animation);
 animation.onfinish=()=>{if(cartFeedbackAnimations.get(node)===animation)cartFeedbackAnimations.delete(node);};
}
function refreshCart(){
 if(!$('currentCart')){render();return;}
 const list=$('currentCart').querySelector('.cart-items'),scroll=list.scrollTop,byId=new Map(state.products.map(p=>[p.id,p]));
 const template=document.createElement('template');template.innerHTML=renderCart(totals(byId),byId);
 const nextList=template.content.querySelector('.cart-items'),oldRows=new Map([...list.querySelectorAll('[data-cart-item]')].map(el=>[el.dataset.cartItem,el])),feedback=[];
 let cursor=list.firstElementChild;
 for(const fresh of [...nextList.children]){
  const existing=oldRows.get(fresh.dataset.cartItem);let row=fresh;
  if(existing){row=existing;if(row.innerHTML!==fresh.innerHTML||row.className!==fresh.className){row.className=fresh.className;patchCartRow(row,fresh);feedback.push([row,false]);}oldRows.delete(fresh.dataset.cartItem);}
  else if(fresh.dataset.cartItem)feedback.push([row,true]);
  if(row!==cursor)list.insertBefore(row,cursor);else cursor=cursor.nextElementSibling;
 }
 while(cursor){const next=cursor.nextElementSibling;cursor.remove();cursor=next;}
 for(const id of ['cartCount','subtotal','due'])$(id).textContent=template.content.querySelector('#'+id).textContent;
 $('discount').value=template.content.querySelector('#discount').value;
 $('checkout').disabled=template.content.querySelector('#checkout').disabled;
 const bar=$('mobileCart'),freshBar=template.content.querySelector('#mobileCart'),changed=bar.innerHTML!==freshBar.innerHTML;
 if(changed){[...bar.children].forEach((el,i)=>el.textContent=freshBar.children[i].textContent);cartFeedback(bar);cartFeedback($('due'));}
 list.scrollTop=scroll;wireCart();syncCartAccessibility();
 feedback.forEach(([row,enter])=>cartFeedback(row,enter));
}

