function addToCart(id,delta){return transact(s=>{const p=s.products.find(p=>p.id===id),l=s.cart.find(l=>l.productId===id),qty=(l?.qty||0)+delta;if(p.deleted)fail('商品已删除');if(qty<=0)s.cart=s.cart.filter(l=>l.productId!==id);else if(l)l.qty=qty;else s.cart.push({productId:id,qty});const subtotal=s.cart.reduce((sum,l)=>sum+cartUnitPrice(l,s.products.find(p=>p.id===l.productId))*l.qty,0);s.discount=Math.min(s.discount,subtotal)},'cart');}
function addMovement(s,p,delta,type,note,unitCost){s.movements.push({id:uid(),productId:p.id,name:p.name,sku:p.sku,code:p.code,delta,after:p.stock,type,note,...(unitCost===undefined?{}:{unitCost}),actor:POSAuth.actor(),time:new Date().toISOString()});}
